do $$
declare
  v_pkg uuid; v_expression uuid; v_opening uuid; v_asset uuid; v_obs15 uuid; v_obs16 uuid; v_obs17 uuid; v_proposal uuid; v_block uuid; v_unit uuid;
begin
  select p.id,p.expression_id into v_pkg,v_expression from wnph.publication_source_packages p where p.canonical_key='virginia-house-wife:1824-functional-semantic-source:v1';
  if v_pkg is null then raise exception 'WNPH Virginia dry-beef candidate: source package is missing'; end if;
  if exists(select 1 from wnph.publication_semantic_units u where u.source_package_id=v_pkg and u.unit_key='virginia-house-wife:1824:semantic:dry-beef-for-summer-use' and not exists(select 1 from wnph.publication_semantic_units n where n.supersedes_unit_id=u.id)) then return; end if;
  select b.id into v_opening from wnph.publication_source_blocks b where b.source_package_id=v_pkg and b.block_key='virginia-house-wife:1824:sequence:opening-preservation' and not exists(select 1 from wnph.publication_source_blocks n where n.supersedes_block_id=b.id) order by b.created_at desc limit 1;
  if v_opening is null then raise exception 'WNPH Virginia dry-beef candidate: corrected opening container is missing'; end if;

  insert into wnph.publication_source_assets(source_package_id,asset_key,asset_role,source_locator,storage_uri,media_type,metadata)
  values(v_pkg,'virginia-house-wife:1824:textgrid-transcription','source_surface',jsonb_build_object('repository','TextGrid Repository','resource_uri','https://sandbox.textgridrep.org/browse/textgrid%3A2s1gn.0?mode=gallery','edition_statement','Washington: Printed by Davis and Force, 1824','comparison_scope','exact-1824 transcription comparison only'),'https://sandbox.textgridrep.org/browse/textgrid%3A2s1gn.0?mode=gallery','text/html',jsonb_build_object('surface_kind','repository_transcription_surface','source_kind','human-readable repository transcription','controlling_witness',false,'comparison_only',true,'loc_witness_remains_controlling',true)) returning id into v_asset;

  insert into wnph.publication_source_observations(source_asset_id,observation_key,observation_kind,ordinal,text_candidate,coordinate_unit,confidence,derivation_method,source_format,processor,external_locator,metadata)
  values(v_asset,'virginia-house-wife:1824:p15:dry-beef','page_text',15,'TO DRY BEEF FOR SUMMER USE.\n\nThe best pieces for this purpose are the thin briskets, or that part of the plate which is farthest from the shoulder of the animal, the round and rib pieces, that are commonly used for roasting. These should not be cut with long ribs, and the back-bones must be sawed off as close as possible, that the pieces may lay flat in the dish. About the middle of February, select your beef from an animal, well fatted with corn, and which, when killed,','surface',0.98,'exact_1824_textgrid_transcription_comparison','text/html transcription',jsonb_build_object('provider','TextGrid Repository','engine','repository_transcription','edition','1824'),jsonb_build_object('printed_page',15,'resource_uri','https://sandbox.textgridrep.org/browse/textgrid%3A2s1gn.0?mode=gallery'),jsonb_build_object('comparison_only',true,'controlling_witness_page_image_inspected',false)) returning id into v_obs15;

  insert into wnph.publication_source_observations(source_asset_id,observation_key,observation_kind,ordinal,text_candidate,coordinate_unit,confidence,derivation_method,source_format,processor,external_locator,metadata)
  values(v_asset,'virginia-house-wife:1824:p16:dry-beef','page_text',16,'will weigh one hundred and fifty per quarter—larger oxen are always coarse.—Salt the pieces as directed, let them lie one fortnight, then put them in brine, where they must remain three weeks, take them out at the end of the time, wipe them quite dry, rub them over with bran, and hang them in a cool, dry, and, if possible, dark place, that the flies may not get to them : they must be suspended, and not allowed to touch any thing. It will be necessary, in the course of the summer, to look them over occasionally, and after a long wet season, to lay them in the sun a few hours. Your tongues may be dried in the same manner: Make a little hole in the root, run a twine through it and suspend it. These dried meats must be put in a good quantity of water, to soak the night before they are to be used. In boiling, it is absolutely necessary to have a large quantity of water, to put the beef in while the water is cold, to boil steadily, skimming the pot, until the bones are ready to fall out; and, if a tongue, till the skin peels off with perfect ease : the skin must also be taken from the beef. The housekeeper who will buy good','surface',0.98,'exact_1824_textgrid_transcription_comparison','text/html transcription',jsonb_build_object('provider','TextGrid Repository','engine','repository_transcription','edition','1824'),jsonb_build_object('printed_page',16,'resource_uri','https://sandbox.textgridrep.org/browse/textgrid%3A2s1gn.0?mode=gallery'),jsonb_build_object('comparison_only',true,'controlling_witness_page_image_inspected',false)) returning id into v_obs16;

  insert into wnph.publication_source_observations(source_asset_id,observation_key,observation_kind,ordinal,text_candidate,coordinate_unit,confidence,derivation_method,source_format,processor,external_locator,metadata)
  values(v_asset,'virginia-house-wife:1824:p17:dry-beef','page_text',17,'ox beef, and follow these directions exactly, may be assured of always having delicious beef on her table. Ancient prejudice has established a notion, that meat killed in the decrease of the moon, will draw up when cooked. The true cause of this shrinking, may be found in the old age of the animal, or in its diseased state, at the time of killing. The best age is from three to five years.\n\nFew persons are aware of the injury they sustain, by eating the flesh of diseased animals. None but the Jewish butchers, who are paid exclusively for it, attend to this important circumstance. The best rule for judging that I have been able to discover, is the colour of the fat. When the fat of beef is a high shade of yellow, I reject it. If the fat of veal, mutton, lamb, or pork, have the slightest tinge of yellow, I avoid it as diseased. The same rule holds good when applied to poultry.','surface',0.98,'exact_1824_textgrid_transcription_comparison','text/html transcription',jsonb_build_object('provider','TextGrid Repository','engine','repository_transcription','edition','1824'),jsonb_build_object('printed_page',17,'resource_uri','https://sandbox.textgridrep.org/browse/textgrid%3A2s1gn.0?mode=gallery'),jsonb_build_object('comparison_only',true,'controlling_witness_page_image_inspected',false)) returning id into v_obs17;

  insert into wnph.publication_source_reconstruction_proposals(source_package_id,proposal_key,target_parent_block_id,proposed_block_key,proposed_ordinal,proposed_block_type,proposed_semantic_role,proposed_text_content,proposed_reading_state,source_observation_ids,confidence,disposition,review_reasons,proposed_properties,proposed_source_provenance,algorithm)
  values(v_pkg,'virginia-house-wife:1824:dry-beef-for-summer-use:reconstruction:v1',v_opening,'virginia-house-wife:1824:to-dry-beef-for-summer-use',2,'instruction','preservation_and_storage_protocol','TO DRY BEEF FOR SUMMER USE.\n\nThe best pieces for this purpose are the thin briskets, or that part of the plate which is farthest from the shoulder of the animal, the round and rib pieces, that are commonly used for roasting. These should not be cut with long ribs, and the back-bones must be sawed off as close as possible, that the pieces may lay flat in the dish. About the middle of February, select your beef from an animal, well fatted with corn, and which, when killed, will weigh one hundred and fifty per quarter—larger oxen are always coarse.—Salt the pieces as directed, let them lie one fortnight, then put them in brine, where they must remain three weeks, take them out at the end of the time, wipe them quite dry, rub them over with bran, and hang them in a cool, dry, and, if possible, dark place, that the flies may not get to them : they must be suspended, and not allowed to touch any thing. It will be necessary, in the course of the summer, to look them over occasionally, and after a long wet season, to lay them in the sun a few hours. Your tongues may be dried in the same manner: Make a little hole in the root, run a twine through it and suspend it. These dried meats must be put in a good quantity of water, to soak the night before they are to be used. In boiling, it is absolutely necessary to have a large quantity of water, to put the beef in while the water is cold, to boil steadily, skimming the pot, until the bones are ready to fall out; and, if a tongue, till the skin peels off with perfect ease : the skin must also be taken from the beef. The housekeeper who will buy good ox beef, and follow these directions exactly, may be assured of always having delicious beef on her table. Ancient prejudice has established a notion, that meat killed in the decrease of the moon, will draw up when cooked. The true cause of this shrinking, may be found in the old age of the animal, or in its diseased state, at the time of killing. The best age is from three to five years.\n\nFew persons are aware of the injury they sustain, by eating the flesh of diseased animals. None but the Jewish butchers, who are paid exclusively for it, attend to this important circumstance. The best rule for judging that I have been able to discover, is the colour of the fat. When the fat of beef is a high shade of yellow, I reject it. If the fat of veal, mutton, lamb, or pork, have the slightest tinge of yellow, I avoid it as diseased. The same rule holds good when applied to poultry.','candidate',array[v_obs15,v_obs16,v_obs17],0.97,'review',jsonb_build_array('TextGrid is a comparison transcription, not the controlling LOC witness','LOC pages 16-17 have not passed direct page-image verification'),jsonb_build_object('historical_unit_type','preservation_and_storage_protocol','printed_pages',jsonb_build_array(15,16,17),'modern_safety_assessed',false,'historical_health_beliefs_present',true),jsonb_build_object('text_authority','Library of Congress 1824 first edition remains controlling; exact-1824 TextGrid transcription supplies comparison reading only','source_locators',jsonb_build_array(jsonb_build_object('printed_page',15,'comparison_asset','virginia-house-wife:1824:textgrid-transcription'),jsonb_build_object('printed_page',16,'comparison_asset','virginia-house-wife:1824:textgrid-transcription'),jsonb_build_object('printed_page',17,'comparison_asset','virginia-house-wife:1824:textgrid-transcription')),'derivation_method','exact-1824 comparison transcription reconstruction pending controlling-witness page verification','verification_status','candidate_comparison_only'),jsonb_build_object('engine','wnph_exact_edition_comparison_reconstructor','version','1')) returning id into v_proposal;

  insert into wnph.publication_source_blocks(source_package_id,block_key,parent_block_id,ordinal,block_type,semantic_role,text_content,properties,source_provenance,reading_state)
  values(v_pkg,'virginia-house-wife:1824:to-dry-beef-for-summer-use',v_opening,2,'instruction','preservation_and_storage_protocol',(select proposed_text_content from wnph.publication_source_reconstruction_proposals where id=v_proposal),jsonb_build_object('historical_unit_type','preservation_and_storage_protocol','printed_pages',jsonb_build_array(15,16,17),'modern_safety_assessed',false,'historical_health_beliefs_present',true,'reconstruction_proposal_id',v_proposal::text),jsonb_build_object('text_authority','Library of Congress 1824 first edition remains controlling; exact-1824 TextGrid transcription supplies comparison reading only','source_locators',jsonb_build_array(jsonb_build_object('printed_page',15,'asset_key','virginia-house-wife:1824:textgrid-transcription'),jsonb_build_object('printed_page',16,'asset_key','virginia-house-wife:1824:textgrid-transcription'),jsonb_build_object('printed_page',17,'asset_key','virginia-house-wife:1824:textgrid-transcription')),'derivation_method','exact_1824_textgrid_transcription_comparison','controlling_witness','Library of Congress 1824 first edition','candidate_reading_basis','exact-1824 TextGrid comparison transcription','comparison_asset_key','virginia-house-wife:1824:textgrid-transcription','verification_status','candidate_comparison_only','source_verified',false),'candidate') returning id into v_block;

  insert into wnph.publication_semantic_units(expression_id,source_package_id,unit_key,ordinal,unit_type,source_title,semantic_status,confidence,derivation_method,properties,source_provenance)
  values(v_expression,v_pkg,'virginia-house-wife:1824:semantic:dry-beef-for-summer-use',2,'preservation_and_storage_protocol','TO DRY BEEF FOR SUMMER USE.','candidate',0.96,'functional_semantic_parse_from_exact_1824_comparison_transcription',jsonb_build_object('historical_container','unsectioned opening instruction sequence','printed_pages',jsonb_build_array(15,16,17),'primary_function','preserve beef for summer use','modern_safety_assessed',false,'modern_normalization_applied',false,'historical_health_beliefs_present',true),jsonb_build_object('source_block_id',v_block::text,'source_verified',false,'source_state','candidate','controlling_witness','1824 LOC first edition','comparison_transcription','TextGrid exact 1824')) returning id into v_unit;

  insert into wnph.publication_semantic_claims(semantic_unit_id,source_block_id,claim_key,ordinal,claim_kind,subject_key,predicate,object_text,quantity_value,quantity_unit,quantity_text,temporal_text,condition_text,claim_status,confidence,derivation_method,properties,source_provenance)
  select v_unit,v_block,x.claim_key,x.ordinal,x.claim_kind,x.subject_key,x.predicate,x.object_text,x.quantity_value,x.quantity_unit,x.quantity_text,x.temporal_text,x.condition_text,'candidate',x.confidence,'historical_function_parse_without_modern_normalization',x.properties,jsonb_build_object('source_verified',false,'source_pages',jsonb_build_array(15,16,17),'comparison_transcription','TextGrid exact 1824','controlling_witness','LOC 1824')
  from (values
    ('preferred-cuts',1,'material_selection','beef','prefer_cuts','thin briskets; far plate; round and rib roasting pieces',null::numeric,null::text,null::text,null::text,null::text,0.98::numeric,'{}'::jsonb),
    ('bone-preparation',2,'preparation','beef_pieces','prepare_shape','do not leave long ribs; saw back-bones close so pieces lay flat',null,null,null,null,null,0.98,'{}'::jsonb),
    ('season-start',3,'seasonal_timing','dry_beef','begin','select and begin curing',null,null,null,'middle of February',null,0.99,'{}'::jsonb),
    ('animal-feed',4,'material_selection','animal','prefer_state','well fatted with corn',null,null,null,null,null,0.98,'{}'::jsonb),
    ('animal-size',5,'material_selection','animal','target_weight','one hundred and fifty per quarter',150,'pound_per_quarter','one hundred and fifty per quarter',null,'when killed',0.97,jsonb_build_object('historical_measure_context','quarter carcass weight')),
    ('larger-oxen',6,'historical_quality_judgment','larger_oxen','classified_as','always coarse',null,null,null,null,null,0.95,jsonb_build_object('author_judgment',true)),
    ('salt-stage',7,'process_stage','beef','dry_salt','salt as directed',null,null,null,'one fortnight',null,0.99,jsonb_build_object('sequence_stage',1)),
    ('brine-stage',8,'process_stage','beef','brine','remain in brine',null,null,null,'three weeks',null,0.99,jsonb_build_object('sequence_stage',2)),
    ('bran-and-hang',9,'process_stage','beef','dry_and_hang','wipe quite dry; rub with bran; hang',null,null,null,null,null,0.99,jsonb_build_object('sequence_stage',3)),
    ('hanging-environment',10,'storage_condition','dried_beef','store_in','cool, dry, and if possible dark place',null,null,null,'summer','exclude flies',0.99,'{}'::jsonb),
    ('suspension',11,'storage_condition','dried_beef','suspend','must not touch any thing',null,null,null,null,null,0.99,'{}'::jsonb),
    ('summer-inspection',12,'maintenance','dried_beef','inspect','look over occasionally',null,null,null,'course of the summer',null,0.98,'{}'::jsonb),
    ('wet-season-sun',13,'maintenance','dried_beef','sun_dry','lay in sun a few hours',null,null,null,'after a long wet season',null,0.98,'{}'::jsonb),
    ('tongue-extension',14,'scope_extension','tongues','use_same_method','may be dried in the same manner',null,null,null,null,null,0.99,'{}'::jsonb),
    ('tongue-suspension',15,'equipment_method','tongue','suspend_with','twine through a little hole in the root',null,null,null,null,null,0.98,'{}'::jsonb),
    ('preuse-soak',16,'preparation','dried_meat','soak','good quantity of water',null,null,null,'night before use',null,0.99,'{}'::jsonb),
    ('boil-water',17,'cooking_condition','dried_beef','boil_in','large quantity of water; put beef in while water is cold',null,null,null,null,null,0.99,'{}'::jsonb),
    ('boil-endpoint',18,'cooking_endpoint','beef','boil_until','bones are ready to fall out; skim pot while boiling steadily',null,null,null,null,null,0.98,'{}'::jsonb),
    ('tongue-endpoint',19,'cooking_endpoint','tongue','boil_until','skin peels off with perfect ease',null,null,null,null,null,0.98,'{}'::jsonb),
    ('remove-skin',20,'finishing','beef','remove','skin',null,null,null,'after boiling',null,0.98,'{}'::jsonb),
    ('animal-age',21,'historical_quality_rule','animal','preferred_age','three to five years',3,'year_minimum','from three to five years',null,null,0.97,jsonb_build_object('maximum_value',5,'maximum_unit','year')),
    ('moon-cause-rejected',22,'historical_causal_rejection','meat_shrinkage','not_caused_by','killing in the decrease of the moon',null,null,null,null,null,0.98,jsonb_build_object('historical_belief_context',true)),
    ('shrinkage-cause',23,'historical_causal_claim','meat_shrinkage','attributed_to','old age of animal or diseased state at killing',null,null,null,null,null,0.95,jsonb_build_object('modern_validity_assessed',false)),
    ('beef-fat-color-rule',24,'historical_health_rule','beef','reject_if','fat is a high shade of yellow',null,null,null,null,null,0.97,jsonb_build_object('modern_safety_assessed',false,'do_not_use_as_modern_safety_rule',true)),
    ('other-fat-color-rule',25,'historical_health_rule','veal_mutton_lamb_pork_poultry','avoid_if','fat has yellow tinge',null,null,null,null,null,0.96,jsonb_build_object('modern_safety_assessed',false,'do_not_use_as_modern_safety_rule',true))
  ) as x(claim_key,ordinal,claim_kind,subject_key,predicate,object_text,quantity_value,quantity_unit,quantity_text,temporal_text,condition_text,confidence,properties);
end $$;